+export function matchEach<const input, output = symbols.unset>(value: input): MatchEach<input, output>;
+export function matchEach<input, output = symbols.unset>(): MatchEach<input, output>;
+export function matchEach<input, output = symbols.unset>(value?: input): MatchEach<input, output> {
+  return new MatchEachExpression<input, output>(arguments.length === 1, value, []) as any;
+}
+
+class MatchEachExpression<input, output> {
+  constructor(
+    private readonly hasValue: boolean,
+    private readonly value: input | undefined,
+    private readonly operations: Operation<input, output>[]
+  ) {}
+
+  with(...args: any[]): MatchEachExpression<input, output> {
+    const handler = args[args.length - 1] as Clause<input, output>['handler'];
+    const patterns: Pattern<input>[] = [args[0]];
+    let predicate: ((value: input) => unknown) | undefined;
+    if (args.length === 3 && typeof args[1] === 'function') predicate = args[1];
+    else if (args.length > 2) patterns.push(...args.slice(1, -1));
+    return this.add({ type: 'clause', clause: { patterns, predicate, handler } });
+  }
+
+  when(predicate: (value: input) => unknown, handler: Clause<input, output>['handler']) {
+    return this.add({ type: 'clause', clause: { predicate, handler } });
+  }
+
+  tap(callback: (result: output) => unknown) {
+    return this.add({ type: 'tap', callback });
+  }
+
+  otherwise(handler: (value: input) => output): output[] {
+    return this.evaluateRequired(this.requireValue(), handler);
+  }
+
+  exhaustive(fallback?: (value: input) => output): output[] {
+    return this.evaluateRequired(this.requireValue(), fallback);
+  }
